steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projects(first: 50, filter: {name: {contains: \"Checkout Redesign\"}}) { nodes { id name lead { id name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projects(first: 10) { nodes { id name } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { __schema { queryType { fields { name } } } }"
  }' | python3 -c "import sys,json; data=json.load(sys.stdin); fields=[f['name'] for f in data['data']['__schema']['queryType']['fields']]; print('\n'.join(sorted(fields)))"

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"Query\") { fields { name args { name type { name kind ofType { name } } } } } }"
  }' | python3 -c "
import sys, json
data = json.load(sys.stdin)
fields = data['data']['__type']['fields']
for f in fields:
    if f['name'] in ('projects', 'searchProjects', 'projectMilestones'):
        print(f['name'], ':', [a['name'] for a in f.get('args', [])])
"

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { searchProjects(term: \"Checkout Redesign\") { nodes { id name lead { id name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { project(id: \"p-1\") { id name lead { id name } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"Query\") { fields { name args { name type { name kind ofType { name kind } } } } } }"
  }' | python3 -c "
import sys, json
data = json.load(sys.stdin)
fields = data['data']['__type']['fields']
for f in fields:
    if f['name'] == 'project':
        print(json.dumps(f, indent=2))
"

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { project(id: \"p-2\") { id name lead { id name } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projectMilestones(first: 100) { nodes { id name targetDate project { id name lead { id name } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projectMilestones(first: 100, includeArchived: true) { nodes { id name targetDate project { id name lead { id name } } } } }"
  }'
